\title{Functional Equations Enforce Primitivity:\\ A Genuine Root-Number Reciprocity Law for Prime Moduli}
\author{Aristotle}
\date{July 13, 2026}

\begin{document}

\begin{abstract}
The functional equation of a Dirichlet $L$-function carries a constant of
proportionality, the \emph{root number} $W(\chi)$, a complex number of absolute
value one whose exact value encodes delicate arithmetic. We establish an exact
reciprocity law for the root numbers of a character and its inverse. For a
nontrivial Dirichlet character $\chi$ modulo a prime $p$ we prove
$W(\chi)\,W(\chi^{-1}) = 1$, an honest equality of complex numbers rather than
the self-referential identity form $W(\chi)\,W(\chi^{-1})\,\Lam(\chi,s) =
\Lam(\chi,s)$ available without a non-vanishing hypothesis. The engine is the
field-case Gauss-sum product identity $\tau(\chi)\,\tau(\chi^{-1}) = \chi(-1)\,p$,
combined with a parity computation showing that the normalizing factor $i^{2a}$
cancels $\chi(-1)$ exactly. From the reciprocity law we deduce that root numbers
of nontrivial characters modulo a prime are nonzero, that $W(\chi^{-1}) =
W(\chi)^{-1}$, that real (quadratic) characters have root number satisfying
$W(\chi)^2 = 1$ --- hence a pure sign --- and a clean solved form of the functional
equation, $\Lam(\chi^{-1}, s) = p^{-(s-1/2)}\,W(\chi^{-1})\,\Lam(\chi, 1-s)$. We
explain why the primality (field) hypothesis is essential: for composite moduli,
imprimitive characters can have vanishing Gauss sums, so the clean law must
restrict to primitive characters --- a concrete manifestation of the principle
that a clean functional equation enforces primitivity of the coefficient
function.
\end{abstract}

\maketitle

\section{Introduction}

Dirichlet $L$-functions occupy a foundational position in analytic number
theory. To a Dirichlet character $\chi$ modulo $N$ one associates the series
\[
L(\chi, s) = \sum_{n=1}^{\infty} \frac{\chi(n)}{n^s}, \qquad \re(s) > 1,
\]
which admits meromorphic continuation to the whole complex plane and satisfies a
functional equation relating $s$ to $1-s$. The most refined form of this
symmetry uses the completed $L$-function, and the reflection it satisfies
features a multiplicative constant $W(\chi)$, the \emph{root number}, with
$|W(\chi)| = 1$.

The root number is arithmetically deep. Its sign, for self-dual objects, governs
the parity of ranks in the Birch--Swinnerton-Dyer circle of ideas and appears
throughout the theory of automorphic $L$-functions. This paper isolates and
proves an exact reciprocity law relating $W(\chi)$ and $W(\chi^{-1})$. Our
contributions are:
\begin{enumerate}
  \item a proof that $W(\chi)\,W(\chi^{-1}) = 1$ as an honest identity of complex
    numbers, for every nontrivial character $\chi$ of prime modulus $p$
    (Theorem~\ref{thm:reciprocity});
  \item a suite of consequences: non-vanishing of the root number
    (Theorem~\ref{thm:nonvanish}), the reciprocal law $W(\chi^{-1}) =
    W(\chi)^{-1}$ (Theorem~\ref{thm:recip}), and $W(\chi)^2 = 1$ for real
    characters (Theorem~\ref{thm:quad});
  \item a solved form of the functional equation for primitive characters
    (Theorem~\ref{thm:solved});
  \item a precise account of why primality is essential (Section~\ref{sec:why}).
\end{enumerate}

\section{Definitions}

\begin{definition}[Dirichlet character]
For $N \geq 1$, a \emph{Dirichlet character modulo $N$} is a completely
multiplicative function $\chi : \Z \to \C$ that is periodic modulo $N$ and
supported on integers coprime to $N$. Equivalently, $\chi$ arises from a
homomorphism $(\Z/N\Z)^\times \to \C^\times$, extended by zero. The
\emph{inverse} character $\chi^{-1}$ is the pointwise inverse on units; it agrees
with the complex conjugate $\overline{\chi}$.
\end{definition}

\begin{definition}[Parity]
Since $\chi(-1)^2 = \chi(1) = 1$, we have $\chi(-1) \in \{+1,-1\}$. We say $\chi$
is \emph{even} if $\chi(-1) = +1$ and \emph{odd} if $\chi(-1) = -1$, and set the
parity exponent $a(\chi) = 0$ if $\chi$ is even and $a(\chi) = 1$ if $\chi$ is
odd.
\end{definition}

\begin{definition}[Completed $L$-function]
For a primitive character $\chi$ modulo $N$,
\[
\Lam(\chi, s) = \left(\frac{N}{\pi}\right)^{(s + a(\chi))/2}
  \Gamma\!\left(\frac{s + a(\chi)}{2}\right) L(\chi, s),
\]
which satisfies the functional equation
\begin{equation}\label{eq:fe}
\Lam(\chi, 1-s) = W(\chi)\, N^{\,s - 1/2}\, \Lam(\chi^{-1}, s). \tag{FE}
\end{equation}
\end{definition}

\begin{definition}[Gauss sum and root number]
With the standard additive character $\psi(x) = e^{2\pi i x/N}$,
\[
\tau(\chi) = \sum_{x \bmod N} \chi(x)\, e^{2\pi i x / N},
\qquad
W(\chi) = \frac{\tau(\chi)}{i^{\,a(\chi)}\, \sqrt{N}}.
\]
For primitive $\chi$, $|\tau(\chi)| = \sqrt N$, hence $|W(\chi)| = 1$.
\end{definition}

\section{Gauss-sum arithmetic over a prime field}

\begin{lemma}[Inversion preserves parity]\label{lem:parity}
For any Dirichlet character $\chi$ modulo $N$, $\chi$ is even iff $\chi^{-1}$ is
even; equivalently $a(\chi) = a(\chi^{-1})$.
\end{lemma}

\begin{proof}
Since $\chi^{-1}(-1) = \chi(-1)^{-1}$ and $\chi(-1) \in \{+1,-1\}$ is its own
inverse, $\chi^{-1}(-1) = \chi(-1)$; hence $\chi^{-1}(-1) = 1 \iff \chi(-1) = 1$.
\end{proof}

\begin{lemma}[Field-case Gauss-sum product]\label{lem:gauss}
Let $p$ be prime and $\chi$ a nontrivial Dirichlet character modulo $p$. Then
\[
\tau(\chi)\,\tau(\chi^{-1}) = \chi(-1)\, p.
\]
\end{lemma}

\begin{proof}
Over the field $\Z/p\Z$, the cross Gauss-sum product against inverse additive
characters gives $\tau_\psi(\chi)\,\tau_{\psi^{-1}}(\chi^{-1}) =
\#(\Z/p\Z) = p$ for nontrivial $\chi$ and primitive $\psi$ (the standard additive
character is primitive because $p$ is prime). The additive reflection
$\chi^{-1}(-1)\,\tau_{\psi^{-1}}(\chi^{-1}) = \tau_\psi(\chi^{-1})$ follows from
the substitution $x \mapsto -x$, since $\psi^{-1}(x) = \psi(-x)$. Writing $c =
\chi(-1)$ with $c^2 = 1$ and $\chi^{-1}(-1) = c$, we get
$\tau_{\psi^{-1}}(\chi^{-1}) = c\,\tau_\psi(\chi^{-1})$, so
\[
p = \tau_\psi(\chi)\,\tau_{\psi^{-1}}(\chi^{-1})
  = c\,\bigl(\tau_\psi(\chi)\,\tau_\psi(\chi^{-1})\bigr).
\]
Multiplying by $c$ and using $c^2 = 1$ gives $\tau_\psi(\chi)\,\tau_\psi(\chi^{-1})
= c\,p = \chi(-1)\,p$.
\end{proof}

\section{The reciprocity law}

\begin{theorem}[Genuine root-number reciprocity]\label{thm:reciprocity}
Let $p$ be prime and $\chi$ a nontrivial Dirichlet character modulo $p$. Then
\[
W(\chi)\,W(\chi^{-1}) = 1.
\]
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:parity}, $a(\chi) = a(\chi^{-1}) =: a$. Hence
\[
W(\chi)\,W(\chi^{-1})
  = \frac{\tau(\chi)\,\tau(\chi^{-1})}{i^{2a}\,p}
  = \frac{\chi(-1)\,p}{i^{2a}\,p}
  = \frac{\chi(-1)}{i^{2a}},
\]
using $(\sqrt p)^2 = p$ and Lemma~\ref{lem:gauss}. If $\chi$ is even, $a=0$ and
$\chi(-1)=1$, giving $1$. If $\chi$ is odd, $a=1$ and $\chi(-1)=-1$, giving
$-1/i^2 = -1/(-1) = 1$. In both cases the product is $1$.
\end{proof}

The normalization $i^{a}$ is designed so that $i^{2a} = \chi(-1)$, producing exact
cancellation.

\section{Immediate consequences}

\begin{theorem}[Non-vanishing]\label{thm:nonvanish}
For $p$ prime and $\chi$ nontrivial modulo $p$, $W(\chi) \neq 0$.
\end{theorem}
\begin{proof}
If $W(\chi) = 0$ then $W(\chi)\,W(\chi^{-1}) = 0 \neq 1$, contradicting
Theorem~\ref{thm:reciprocity}.
\end{proof}

\begin{theorem}[Reciprocal law]\label{thm:recip}
Under the hypotheses of Theorem~\ref{thm:reciprocity}, $W(\chi^{-1}) =
W(\chi)^{-1}$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:nonvanish}, $W(\chi) \neq 0$; divide the identity of
Theorem~\ref{thm:reciprocity} by $W(\chi)$.
\end{proof}

\begin{theorem}[Quadratic characters carry a sign]\label{thm:quad}
Let $p$ be prime and $\chi$ a nontrivial real (self-dual) character modulo $p$,
i.e. $\chi^{-1} = \chi$. Then $W(\chi)^2 = 1$, hence $W(\chi) \in \{+1,-1\}$.
\end{theorem}
\begin{proof}
Substitute $\chi^{-1} = \chi$ into Theorem~\ref{thm:reciprocity}.
\end{proof}

Gauss's evaluation of the quadratic Gauss sum refines this to $W(\chi) = +1$ for
the Legendre symbol; the statement ``$W(\chi)$ is a sign'' is the part following
for free from reciprocity.

\section{The functional equation, solved}

\begin{theorem}[Solved functional equation]\label{thm:solved}
Let $p$ be prime and $\chi$ a primitive nontrivial character modulo $p$. For all
$s \in \C$,
\[
\Lam(\chi^{-1}, s) = p^{-(s - 1/2)}\, W(\chi^{-1})\, \Lam(\chi, 1-s).
\]
\end{theorem}
\begin{proof}
The functional equation~\eqref{eq:fe} in the reflected variable reads
$\Lam(\chi, 1-s) = p^{\,s-1/2}\, W(\chi)\, \Lam(\chi^{-1}, s)$. Multiply by
$p^{-(s-1/2)}\,W(\chi^{-1})$; since $p^{-(s-1/2)}\,p^{\,s-1/2} = 1$ and
$W(\chi^{-1})\,W(\chi) = 1$ by Theorem~\ref{thm:reciprocity}, the right-hand side
collapses to $\Lam(\chi^{-1}, s)$.
\end{proof}

\section{Why primality is essential}\label{sec:why}

The argument rests on Lemma~\ref{lem:gauss}, whose proof uses the cross-product
identity $\tau_\psi(\chi)\,\tau_{\psi^{-1}}(\chi^{-1}) = \#(\Z/N\Z)$, valid in
this clean form only when $\Z/N\Z$ is a field, i.e. $N$ prime. For composite $N$
an imprimitive character can have a \emph{vanishing} Gauss sum $\tau(\chi) = 0$,
whereupon the root number is ill-defined and reciprocity fails. Thus the clean
reflection symmetry is a rigidity condition enjoyed only by primitive characters:
the functional equation enforces primitivity of the coefficient function.

\section{Applications and future directions}

Root numbers pervade number theory --- functional equations of $L$-functions of
elliptic curves, modular forms, and automorphic representations all carry them,
and self-dual objects carry root numbers that are signs, controlling e.g. rank
parity in Birch--Swinnerton-Dyer. Natural next steps include: establishing
$|W(\chi)| = 1$ for prime modulus via a conjugation identity; extending the
reciprocity to arbitrary primitive characters modulo composite $N$; refining the
quadratic case to the exact value $W(\chi) = +1$; and establishing a converse
rigidity statement, that any coefficient function whose completed series reflects
cleanly with $|W| = 1$ must be a primitive character.

\end{document}

