"""Demo 1: Verification of the field-case Gauss-sum product identity.

For a nontrivial Dirichlet character chi modulo a prime p, the Gauss sums of chi
and its inverse satisfy  tau(chi) * tau(chi^{-1}) = chi(-1) * p.  This is the
algebraic engine behind root-number reciprocity.
"""

from __future__ import annotations

import cmath
import math
from typing import Callable, Dict, List


def primitive_root(p: int) -> int:
    if p == 2:
        return 1
    phi = p - 1
    factors: List[int] = []
    n, d = phi, 2
    while d * d <= n:
        if n % d == 0:
            factors.append(d)
            while n % d == 0:
                n //= d
        d += 1
    if n > 1:
        factors.append(n)
    for g in range(2, p):
        if all(pow(g, phi // q, p) != 1 for q in factors):
            return g
    raise ValueError("no primitive root")


def make_character(p: int, k: int) -> Callable[[int], complex]:
    g, order = primitive_root(p), p - 1
    dlog: Dict[int, int] = {}
    cur = 1
    for j in range(order):
        dlog[cur] = j
        cur = (cur * g) % p

    def chi(x: int) -> complex:
        r = x % p
        if r == 0:
            return 0j
        return cmath.exp(2j * math.pi * k * dlog[r] / order)

    return chi


def gauss_sum(p: int, chi: Callable[[int], complex]) -> complex:
    return sum(chi(x) * cmath.exp(2j * math.pi * x / p) for x in range(p))


def run(p: int = 13) -> None:
    print(f"Field-case Gauss-sum product identity for p = {p}")
    print("k | tau(chi)*tau(chi^-1)      chi(-1)*p     |error|")
    for k in range(1, p - 1):
        chi = make_character(p, k)
        inv = lambda x, c=chi: c(x).conjugate()
        lhs = gauss_sum(p, chi) * gauss_sum(p, inv)
        rhs = chi(-1) * p
        print(f"{k:2d}| {lhs: .4f}   {rhs: .4f}   {abs(lhs - rhs):.2e}")


if __name__ == "__main__":
    run(13)

"""Demo 2: Root-number reciprocity W(chi) * W(chi^{-1}) = 1 across prime moduli.

The root number is the normalized Gauss sum W(chi) = tau(chi)/(i^a * sqrt(p)),
with a = 0 if chi is even and a = 1 if chi is odd.  For every nontrivial
character modulo a prime, the root numbers of chi and its inverse multiply to 1,
and each has absolute value 1.
"""

from __future__ import annotations

import cmath
import math
from typing import Callable, Dict, List, Tuple


def primitive_root(p: int) -> int:
    if p == 2:
        return 1
    phi = p - 1
    factors: List[int] = []
    n, d = phi, 2
    while d * d <= n:
        if n % d == 0:
            factors.append(d)
            while n % d == 0:
                n //= d
        d += 1
    if n > 1:
        factors.append(n)
    for g in range(2, p):
        if all(pow(g, phi // q, p) != 1 for q in factors):
            return g
    raise ValueError("no primitive root")


def make_character(p: int, k: int) -> Callable[[int], complex]:
    g, order = primitive_root(p), p - 1
    dlog: Dict[int, int] = {}
    cur = 1
    for j in range(order):
        dlog[cur] = j
        cur = (cur * g) % p

    def chi(x: int) -> complex:
        r = x % p
        return 0j if r == 0 else cmath.exp(2j * math.pi * k * dlog[r] / order)

    return chi


def root_number(p: int, chi: Callable[[int], complex]) -> complex:
    tau = sum(chi(x) * cmath.exp(2j * math.pi * x / p) for x in range(p))
    a = 0 if abs(chi(-1) - 1.0) < 1e-9 else 1
    return tau / ((1j ** a) * math.sqrt(p))


def reciprocity_report(p: int) -> Tuple[float, float]:
    """Return (max |W*W_inv - 1|, max ||W| - 1|) over nontrivial characters."""
    max_prod_err = 0.0
    max_abs_err = 0.0
    for k in range(1, p - 1):
        chi = make_character(p, k)
        inv = lambda x, c=chi: c(x).conjugate()
        w, w_inv = root_number(p, chi), root_number(p, inv)
        max_prod_err = max(max_prod_err, abs(w * w_inv - 1.0))
        max_abs_err = max(max_abs_err, abs(abs(w) - 1.0))
    return max_prod_err, max_abs_err


def run(primes: List[int] = (5, 7, 11, 13, 17, 19, 23, 29, 31)) -> None:
    print("p   | max|W*W_inv - 1|   max||W| - 1|")
    for p in primes:
        pe, ae = reciprocity_report(p)
        print(f"{p:3d} | {pe:.2e}          {ae:.2e}")


if __name__ == "__main__":
    run()

