function GaussSum(p, chi):
    total <- 0
    for x in 0 .. p-1:
        total <- total + chi(x) * exp(2*pi*i*x/p)
    return total

function RootNumber(p, chi):
    tau <- GaussSum(p, chi)
    a   <- 0 if chi(-1) = 1 else 1
    return tau / (i^a * sqrt(p))

function ReciprocityResidual(p, chi):
    inv <- (x -> conjugate(chi(x)))
    return | RootNumber(p, chi) * RootNumber(p, inv) - 1 |

function PrimitiveRoot(p):
    factor p-1 into primes {q}
    for g in 2 .. p-1:
        if for all q: g^((p-1)/q) != 1 (mod p): return g

function MakeCharacter(p, k):
    g <- PrimitiveRoot(p)
    build table dlog with dlog[g^j mod p] = j
    return function chi(x):
        if p | x: return 0
        return exp(2*pi*i*k*dlog[x mod p]/(p-1))
